module cnn_act_shreg (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire [1:0] mode,
    input  wire [7:0] din,
    input  wire       flush,
    output wire       out_sat
);
    reg [7:0] win;
    reg [7:0] cnt;
    reg       loaded;
    reg       pristine;
    reg       pv;
    initial win = 8'h00;
    initial cnt = 8'h00;
    initial loaded = 1'b0;
    initial pristine = 1'b1;
    initial pv = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            win      <= 8'h00;
            cnt      <= 8'h00;
            loaded   <= 1'b0;
            pristine <= 1'b1;
        end else if (en) begin
            if (flush) begin
                win      <= 8'h00;
                pristine <= 1'b0;
            end else begin
                case (mode)
                    2'b01: win <= {win[6:0], 1'b0};
                    2'b10: win <= {1'b0, win[7:1]};
                    2'b11: begin
                        win <= din;
                        if (cnt != 8'hFF) cnt <= cnt + 8'h01;
                        if (din != 8'h00) loaded <= 1'b1;
                    end
                    default: win <= win;
                endcase
            end
        end
    end

    assign out_sat = win[7];

    always @(posedge clk)
        if (pv && pristine && $rose(win[7]))
            assert (loaded);
endmodule

