module lssd_scan_dump (
    input  wire        clk,
    input  wire        en,
    input  wire        scan_req,
    input  wire        tdi,
    input  wire        cap,
    input  wire [63:0] sys_d0,
    input  wire [63:0] sys_d1,
    output wire        tdo,
    output wire        busy_o
);
    reg [63:0] l1_0 = 64'd0;
    reg [63:0] l1_1 = 64'd0;
    reg [63:0] l2_0 = 64'd0;
    reg [63:0] l2_1 = 64'd0;
    reg        busy = 1'b0;
    reg        ph   = 1'b0;
    reg [6:0]  sc   = 7'd0;
    reg [7:0]  cd   = 8'd0;

    assign tdo    = l2_1[63];
    assign busy_o = busy;

    always @(posedge clk) begin
        if (en) begin
            if (!busy) begin
                if (scan_req) begin
                    busy <= 1'b1;
                    cd   <= 8'd128;
                    sc   <= 7'd0;
                    ph   <= 1'b0;
                end else begin
                    if (cap) begin
                        l1_0 <= sys_d0;
                        l1_1 <= sys_d1;
                    end
                    l2_0 <= l1_0;
                    l2_1 <= l1_1;
                end
            end else begin
                cd <= cd - 8'd1;
                if (!ph) begin
                    l1_0 <= {l2_0[62:0], tdi};
                    l1_1 <= {l2_1[62:0], l2_0[63]};
                    ph   <= 1'b1;
                end else begin
                    l2_0 <= l1_0;
                    l2_1 <= l1_1;
                    ph   <= 1'b0;
                    if (sc == 7'd63) begin
                        busy <= 1'b0;
                        sc   <= 7'd0;
                    end else begin
                        sc   <= sc + 7'd1;
                    end
                end
            end
        end
    end

    always @(*) begin
        if (busy)
            assert (cd != 8'd0);
        else
            assert (cd == 8'd0);
    end
endmodule

