module round_disp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [34:0] din,
    input wire [1:0] mode_in,
    output reg [6:0] seg
);
    reg [31:0] trunc = 32'd0;
    reg [2:0]  grs = 3'b000;
    reg [1:0]  mode = 2'd0;
    reg [31:0] rounded = 32'd0;
    reg        armed = 1'b0;
    reg        pv = 1'b0;

    function inc_f;
        input [1:0] m;
        input [2:0] g;
        input lsb;
        begin
            case (m)
                2'd0: inc_f = g[2] & (g[1] | g[0] | lsb);
                2'd1: inc_f = 1'b0;
                2'd2: inc_f = g[2] | g[1] | g[0];
                default: inc_f = g[2];
            endcase
        end
    endfunction

    wire ld_inc = inc_f(mode_in, din[2:0], din[3]);
    wire rf_inc = inc_f(mode, grs, trunc[0]);

    always @(posedge clk) begin
        if (rst) begin
            trunc   <= 32'd0;
            grs     <= 3'b000;
            mode    <= 2'd0;
            rounded <= 32'd0;
            armed   <= 1'b0;
        end else if (en) begin
            if (load) begin
                trunc   <= din[34:3];
                grs     <= din[2:0];
                mode    <= mode_in;
                rounded <= din[34:3] + {31'd0, ld_inc};
                armed   <= 1'b1;
            end else begin
                rounded <= trunc + {31'd0, rf_inc};
            end
        end
    end

    always @(*) begin
        case (rounded[3:0])
            4'h0: seg = 7'b1111110;
            4'h1: seg = 7'b0110000;
            4'h2: seg = 7'b1101101;
            4'h3: seg = 7'b1111001;
            4'h4: seg = 7'b0110011;
            4'h5: seg = 7'b1011011;
            4'h6: seg = 7'b1011111;
            4'h7: seg = 7'b1110000;
            4'h8: seg = 7'b1111111;
            4'h9: seg = 7'b1111011;
            4'hA: seg = 7'b1110111;
            4'hB: seg = 7'b0011111;
            4'hC: seg = 7'b1001110;
            4'hD: seg = 7'b0111101;
            4'hE: seg = 7'b1001111;
            default: seg = 7'b1000111;
        endcase
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && !$past(rst) && armed && $stable(trunc) && $stable(grs) && $stable(mode))
            assert ($stable(rounded));
endmodule

