module lut_keccak_rng (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         arm,
    input  wire         start,
    input  wire [127:0] seed,
    input  wire         q_open,
    input  wire         r_close,
    output wire         done,
    output wire [127:0] out
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUNNING = 2'd2, DONE = 2'd3;

    reg [127:0] st = 128'h0;
    reg [4:0]   rnd = 5'd0;
    reg [1:0]   phase = IDLE;
    reg         armed_seen = 1'b0;
    reg         started_seen = 1'b0;
    reg         win = 1'b0;

    assign done = (phase == DONE);
    assign out  = st;

    // round constant ROM, 24 entries
    reg [127:0] rc_val;
    always @(*) begin
        case (rnd)
            5'd0:  rc_val = 128'h0000000000000001_0000000000008082;
            5'd1:  rc_val = 128'h0000000000008082_800000000000808A;
            5'd2:  rc_val = 128'h800000000000808A_8000000080008000;
            5'd3:  rc_val = 128'h8000000080008000_000000000000808B;
            5'd4:  rc_val = 128'h000000000000808B_0000000080000001;
            5'd5:  rc_val = 128'h0000000080000001_8000000080008081;
            5'd6:  rc_val = 128'h8000000080008081_8000000000008009;
            5'd7:  rc_val = 128'h8000000000008009_000000000000008A;
            5'd8:  rc_val = 128'h000000000000008A_0000000000000088;
            5'd9:  rc_val = 128'h0000000000000088_0000000080008009;
            5'd10: rc_val = 128'h0000000080008009_000000008000000A;
            5'd11: rc_val = 128'h000000008000000A_000000008000808B;
            5'd12: rc_val = 128'h000000008000808B_800000000000008B;
            5'd13: rc_val = 128'h800000000000008B_8000000000008089;
            5'd14: rc_val = 128'h8000000000008089_8000000000008003;
            5'd15: rc_val = 128'h8000000000008003_8000000000008002;
            5'd16: rc_val = 128'h8000000000008002_8000000000000080;
            5'd17: rc_val = 128'h8000000000000080_000000000000800A;
            5'd18: rc_val = 128'h000000000000800A_800000008000000A;
            5'd19: rc_val = 128'h800000008000000A_8000000080008081;
            5'd20: rc_val = 128'h8000000080008081_8000000000008080;
            5'd21: rc_val = 128'h8000000000008080_0000000080000001;
            5'd22: rc_val = 128'h0000000080000001_8000000080008008;
            5'd23: rc_val = 128'h8000000080008008_0000000000000001;
            default: rc_val = 128'h0;
        endcase
    end

    // theta
    wire [31:0] l0 = st[31:0];
    wire [31:0] l1 = st[63:32];
    wire [31:0] l2 = st[95:64];
    wire [31:0] l3 = st[127:96];
    wire [31:0] par = l0 ^ l1 ^ l2 ^ l3;
    wire [31:0] th  = {par[30:0], par[31]} ^ {par[0], par[31:1]};
    wire [31:0] t0 = l0 ^ th;
    wire [31:0] t1 = l1 ^ th;
    wire [31:0] t2 = l2 ^ th;
    wire [31:0] t3 = l3 ^ th;
    // rho
    wire [31:0] r0 = t0;
    wire [31:0] r1 = {t1[30:0], t1[31]};
    wire [31:0] r2 = {t2[28:0], t2[31:29]};
    wire [31:0] r3 = {t3[21:0], t3[31:22]};
    // pi
    wire [127:0] s_pi = {r1, r3, r0, r2};
    // chi
    wire [127:0] rl1 = {s_pi[126:0], s_pi[127]};
    wire [127:0] rl2 = {s_pi[125:0], s_pi[127:126]};
    wire [127:0] chi = s_pi ^ (~rl1 & rl2);
    // iota
    wire [127:0] nxt = chi ^ rc_val;

    always @(posedge clk) begin
        if (rst) begin
            st <= 128'h0;
            rnd <= 5'd0;
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            win <= 1'b0;
        end else if (en) begin
            if (r_close)
                win <= 1'b0;
            else if (q_open)
                win <= 1'b1;

            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase <= ARMED;
                        armed_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (start) begin
                        phase <= RUNNING;
                        started_seen <= 1'b1;
                        rnd <= 5'd0;
                        st <= seed;
                    end
                end
                RUNNING: begin
                    st <= nxt;
                    if (rnd == 5'd23) begin
                        phase <= DONE;
                        rnd <= 5'd0;
                    end else begin
                        rnd <= rnd + 5'd1;
                    end
                end
                DONE: begin
                    phase <= IDLE;
                    armed_seen <= 1'b0;
                    started_seen <= 1'b0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (win && phase == 2'd3)
            assert (armed_seen && started_seen);
endmodule

