module axis_luma_compressor (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        s_tvalid,
    input  wire        s_tuser,
    input  wire        s_tlast,
    input  wire [63:0] s_luma,
    input  wire [63:0] thr,
    input  wire [5:0]  ratio_sh,
    input  wire        eof,
    output wire        s_tready,
    output wire        m_tvalid,
    output wire        m_tuser,
    output wire        m_tlast,
    output wire [63:0] m_luma,
    output wire [63:0] o_gain,
    output wire [63:0] o_hist0,
    output wire        o_win
);
    localparam [63:0] UNITY = 64'h0000_0001_0000_0000;
    localparam [63:0] SLEW_LEN = 64'd8;

    reg [63:0] env;
    reg [63:0] gain;
    reg [63:0] tgt;
    reg        pend;
    reg [63:0] cd;
    reg [63:0] step;
    reg [63:0] hist [0:7];
    reg        win;

    integer i;
    initial begin
        env  = 64'd0;
        gain = UNITY;
        tgt  = UNITY;
        pend = 1'b0;
        cd   = 64'd0;
        step = 64'd0;
        win  = 1'b0;
        for (i = 0; i < 8; i = i + 1) hist[i] = UNITY;
    end

    assign s_tready = en;
    wire acc = en && s_tvalid;

    wire [63:0] reduction = (env > thr) ? ((env - thr) >> ratio_sh) : 64'd0;
    wire [63:0] new_tgt   = (reduction >= gain) ? 64'd0 : (gain - reduction);
    wire [63:0] gain_next = (tgt < gain) ? (gain - ((gain - tgt) >> 3))
                                         : (gain + ((tgt - gain) >> 3));
    wire [63:0] env_next  = (s_luma > env) ? (env + ((s_luma - env) >> 2))
                                           : (env - ((env - s_luma) >> 5));

    always @(posedge clk) begin
        if (rst) begin
            env  <= 64'd0;
            gain <= UNITY;
            tgt  <= UNITY;
            pend <= 1'b0;
            cd   <= 64'd0;
            step <= 64'd0;
            win  <= 1'b0;
            for (i = 0; i < 8; i = i + 1) hist[i] <= UNITY;
        end else if (en) begin
            if (acc)
                env <= env_next;
            if (!pend) begin
                if (acc && (env > thr)) begin
                    tgt  <= new_tgt;
                    pend <= 1'b1;
                    cd   <= SLEW_LEN;
                    step <= 64'd0;
                end
            end else begin
                gain <= gain_next;
                hist[step[2:0]] <= gain;
                cd   <= cd - 64'd1;
                step <= step + 64'd1;
                if (step == 64'd7)
                    pend <= 1'b0;
            end
            if (acc && s_tuser)
                win <= 1'b1;
            else if (eof)
                win <= 1'b0;
        end
    end

    wire [127:0] prod = s_luma * gain;
    assign m_luma   = prod[95:32];
    assign m_tvalid = s_tvalid;
    assign m_tuser  = s_tuser;
    assign m_tlast  = s_tlast;
    assign o_gain   = gain;
    assign o_hist0  = hist[0];
    assign o_win    = win;

    always @(*) assert (!(win && pend) || cd != 64'd0);
endmodule


