module qpsk_mw_cfg (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cs,
    input wire di,
    output wire dout,
    output reg do_oe
);
    localparam [2:0] IDLE = 3'd0, START = 3'd1, OPCODE = 3'd2, ADDR = 3'd3, DATA = 3'd4;

    reg [2:0]  phase;
    reg [63:0] cnt;
    reg [7:0]  oa_sr;
    reg [63:0] dat_sr;
    reg [63:0] mem [0:63];
    reg [63:0] wr_cnt;
    reg        pre_commit;
    integer i;

    initial begin
        phase = IDLE; cnt = 64'd0; oa_sr = 8'd0; dat_sr = 64'd0;
        do_oe = 1'b0; wr_cnt = 64'd0; pre_commit = 1'b1;
        for (i = 0; i < 64; i = i + 1) mem[i] = 64'd0;
    end

    wire [7:0]  oa_next  = {oa_sr[6:0], di};
    wire        is_read  = (oa_sr[7:6] == 2'b10);
    wire [63:0] dat_next = {dat_sr[62:0], di};

    assign dout = do_oe & dat_sr[63];

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; cnt <= 64'd0; oa_sr <= 8'd0; dat_sr <= 64'd0;
            do_oe <= 1'b0; wr_cnt <= 64'd0; pre_commit <= 1'b1;
        end else if (en) begin
            if (!cs) begin
                phase <= IDLE;
                do_oe <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (di) phase <= START;
                    end
                    START: begin
                        phase <= OPCODE;
                        cnt <= 64'd2;
                    end
                    OPCODE: begin
                        oa_sr <= oa_next;
                        if (cnt == 64'd1) begin
                            phase <= ADDR;
                            cnt <= 64'd6;
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    ADDR: begin
                        oa_sr <= oa_next;
                        if (cnt == 64'd1) begin
                            phase <= DATA;
                            cnt <= 64'd64;
                            do_oe <= (oa_next[7:6] == 2'b10);
                            if (oa_next[7:6] == 2'b10)
                                dat_sr <= mem[oa_next[5:0]];
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    DATA: begin
                        if (is_read)
                            dat_sr <= {dat_sr[62:0], 1'b0};
                        else
                            dat_sr <= dat_next;
                        if (cnt == 64'd1) begin
                            if (!is_read) begin
                                mem[oa_sr[5:0]] <= dat_next;
                                wr_cnt <= wr_cnt + 64'd1;
                                pre_commit <= 1'b0;
                            end
                            phase <= IDLE;
                            do_oe <= 1'b0;
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    default: begin
                        phase <= IDLE;
                    end
                endcase
            end
        end
    end

    always @(*)
        if (pre_commit)
            assert (!(phase == 3'd3 && do_oe));
