            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
           cyc_cnt   <= 32'd0;
           beat_cnt  <= 32'd0;
           wr0_cnt   <= 16'd0;
           wr1_cnt   <= 16'd0;
           arm_cnt   <= 16'd0;
           clr_cnt   <= 16'd0;
           hit_cnt   <= 16'd0;
           sr_cnt    <= 16'd0;
           done_d    <= 1'b0;
           sr_d      <= 1'b0;
           fsm_d     <= 2'd0;
           wdt_cnt   <= 20'd0;
           wdt_to    <= 1'b0;
           err_bits  <= 4'd0;
           err_code  <= 3'd0;
