            parity[bank] <= parity[bank] ^ sign_bit;
            if (magnitude < low[bank]) begin
                high[bank] <= low[bank];
                low[bank] <= magnitude;
            end else if (magnitude < high[bank]) begin
                high[bank] <= magnitude;
            end
        end
    end
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32,
    parameter GROUPS = 4
