reg pv = 1'b0;
always @(posedge clk) begin
    if (rd_cmd_valid[0] && rd_cmd_ready[0])
        pv <= 1'b1;
end

// A response transfer requires read history; an existing stalled response
// retains its validity and data across a non-reset clock.
always @(posedge clk) begin
    assert (
        (pv || !rd_resp_valid[0] || !rd_resp_ready[0]) &&
        (!pv ||
         !$past(rd_resp_valid[0] && !rd_resp_ready[0] && !rst) ||
         (rd_resp_valid[0] &&
          rd_resp_data[0 +: SEG_DATA_WIDTH] ==
              $past(rd_resp_data[0 +: SEG_DATA_WIDTH])))
    );
end
endmodule

