  reg [31 : 0]  a_reg;
  reg [31 : 0]  a_new;
  reg [31 : 0]  b_reg;
  reg [31 : 0]  b_new;
  reg [31 : 0]  c_reg;
  reg [31 : 0]  c_new;
  reg [31 : 0]  d_reg;
